	// 計装ごとの制御にビューを使用する — 特定の計装を名前で選択して
	// 指数ヒストグラムを使用し、他は明示的バケットを維持する。
	return sdkmetric.NewView(
		sdkmetric.Instrument{Name: "device.command.duration"},
